use rig::memory::InMemoryConversationMemory;
use rig::providers::openai::{self, OpenAI};


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant.")
    .memory(InMemoryConversationMemory::new())
    .build();


// Each conversation id keeps its own history.
agent.prompt("My name is Ada.").conversation("user-42").await?;
let reply = agent.prompt("What's my name?").conversation("user-42").await?;
println!("{}", reply.output());

pub trait ConversationMemory: WasmCompatSend + WasmCompatSync {
    /// Load the full history for a conversation (empty Vec if none).
    fn load<'a>(&'a self, conversation_id: &'a ConversationId)
        -> WasmBoxedFuture<'a, Result<Vec<Message>, MemoryError>>;


    /// Append the messages of a successful turn.
    fn append<'a>(&'a self, conversation_id: &'a ConversationId, messages: Vec<Message>)
        -> WasmBoxedFuture<'a, Result<(), MemoryError>>;


    /// Remove all stored messages for a conversation.
    fn clear<'a>(&'a self, conversation_id: &'a ConversationId)
        -> WasmBoxedFuture<'a, Result<(), MemoryError>>;
}

use rig::memory::{InMemoryConversationMemory, IntoFilter, SlidingWindowMemory};


let memory = InMemoryConversationMemory::new()
    .with_filter(SlidingWindowMemory::last_messages(20).into_filter());

use rig::memory::{HeuristicTokenCounter, InMemoryConversationMemory, IntoFilter, TokenWindowMemory};


let memory = InMemoryConversationMemory::new().with_filter(
    TokenWindowMemory::new(4_000, HeuristicTokenCounter::default()).into_filter(),
);

use rig::memory::{CompactingMemory, InMemoryConversationMemory, SlidingWindowMemory, TemplateCompactor};
use rig::providers::openai::{self, OpenAI};


let memory = CompactingMemory::new(
    InMemoryConversationMemory::new(),
    SlidingWindowMemory::last_messages(20),
    TemplateCompactor::new(), // plain-text rollup, no model call
);


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant.")
    .memory(memory)
    .build();

use rig::providers::openai::{self, OpenAI};


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant. Be concise.")
    .build();


let mut history: Vec<Message> = Vec::new();
agent.chat("My name is Ada.", &mut history).await?;
let reply = agent.chat("What's my name?", &mut history).await?;
println!("{}", reply.output());

let mut history = vec![
    Message::user("What is the Rust programming language?"),
    Message::assistant("Rust is a systems programming language..."),
];


let response = agent.prompt("Who created it?").history(history.clone()).await?;
history.extend(response.messages);
